package com.sunwayworld.framework.converter.string;
import com.sunwayworld.framework.converter.*;import com.sunwayworld.framework.converter.exception.*;import java.math.*;
public enum StringToNumberConverterFactory implements ConverterFactory<String,Number>{INSTANCE;public <T extends Number> Converter<String,T> getConverter(Class<T>targetType){return new StringToNumberConverter<T>(targetType);}private class StringToNumberConverter<T extends Number> implements Converter<String,T>{private final Class<T>numberType;public StringToNumberConverter(Class<T>t){numberType=t;}public Class<String>getSourceType(){return String.class;}public Class<T>getTargetType(){return numberType;}@SuppressWarnings("unchecked")public T convert(String source){if(numberType==null)throw new NullPointerException();if(source==null||source.isEmpty()){if(numberType==Byte.TYPE)return(T)(Object)Character.valueOf((char)0);if(numberType==Short.TYPE)return(T)(Object)Short.valueOf((short)0);if(numberType==Integer.TYPE)return(T)(Object)Integer.valueOf(0);if(numberType==Long.TYPE)return(T)(Object)Long.valueOf(0L);if(numberType==Float.TYPE)return(T)(Object)Float.valueOf(0);if(numberType==Double.TYPE)return(T)(Object)Double.valueOf(0);return null;}String s=source.trim().replace(",","");try{Class<T>t=numberType; if(s.matches(".*\\.[0-9]+9{7}[0-9]?")){int n=s.substring(s.indexOf('.')).length()-3;StringBuilder offset=new StringBuilder("0.");for(int i=0;i<n;i++)offset.append('0');offset.append('1');double corrected=new BigDecimal(s).doubleValue()+Double.parseDouble(offset.toString());java.text.DecimalFormat f=new java.text.DecimalFormat();f.setMaximumFractionDigits(6);f.setGroupingUsed(false);s=f.format(corrected);}if(t==Byte.class||t==Byte.TYPE)return(T)(isHex(s)?Byte.decode(s):Byte.valueOf(s));if(t==Short.class||t==Short.TYPE)return(T)(isHex(s)?Short.decode(s):Short.valueOf(s));if(t==Integer.class||t==Integer.TYPE)return(T)(isHex(s)?Integer.decode(s):Integer.valueOf(s));if(t==Long.class||t==Long.TYPE)return(T)(isHex(s)?Long.decode(s):Long.valueOf(s));if(t==BigInteger.class){if(s.startsWith("+#"))return(T)new BigInteger(s.substring(1));return(T)(isHex(s)?bigHex(s):new BigInteger(s));}if(t==Float.class||t==Float.TYPE)return(T)Float.valueOf(s);if(t==Double.class||t==Double.TYPE)return(T)Double.valueOf(s);if(t==BigDecimal.class||t==Number.class)return(T)new BigDecimal(s);throw new ConvertFailedException(String.class,t,source);}catch(RuntimeException e){throw e;}}private boolean isHex(String s){return s.matches("[-]?((0[xX])|#).+");} private BigInteger bigHex(String s){boolean neg=s.startsWith("-");String t=s.replaceFirst("^[+-]?(0[xX]|#)","");BigInteger n=new BigInteger(t,16);return neg?n.negate():n;}}}
